import json

from django.db import migrations, models


def stack_text_to_json(apps, schema_editor):
    # 칸 종류를 JSON으로 바꾸기 전에, 쉼표로 이어 쓴 글자를 JSON 목록 모양의 글자로 바꿔 둔다.
    # 빈 글자('')는 올바른 JSON이 아니어서 그대로 두면 종류 변경이 실패한다.
    Project = apps.get_model('projects', 'Project')
    for project in Project.objects.all():
        items = [item.strip() for item in project.stack.split(',') if item.strip()]
        project.stack = json.dumps(items, ensure_ascii=False)
        project.save(update_fields=['stack'])


def stack_json_to_text(apps, schema_editor):
    # 되돌릴 때: JSON 목록 모양의 글자를 다시 쉼표로 이어 쓴 글자로 바꾼다.
    Project = apps.get_model('projects', 'Project')
    for project in Project.objects.all():
        project.stack = ', '.join(json.loads(project.stack or '[]'))
        project.save(update_fields=['stack'])


